const fs = require('fs');
const file = 'src/components/modals/AveragingMatrixModal.tsx';
let code = fs.readFileSync(file, 'utf8');

// 1. Add useRef for tracking auto-generation
if (!code.includes('hasAutoGeneratedGridRef')) {
  code = code.replace(
    '  const [useMoneyManagement, setUseMoneyManagement] = useState<boolean>(true);',
    '  const [useMoneyManagement, setUseMoneyManagement] = useState<boolean>(true);\n  const hasAutoGeneratedGridRef = useRef(false);'
  );
}

// 2. Reset the ref when modal opens or bot changes
if (!code.includes('hasAutoGeneratedGridRef.current = false;')) {
  code = code.replace(
    '  useEffect(() => {\n    if (isOpen) {\n      setExecutionMode',
    '  useEffect(() => {\n    if (isOpen) {\n      hasAutoGeneratedGridRef.current = false;\n      setExecutionMode'
  );
}

// 3. Fix the auto-generation useEffect
const oldEffect = `  // Automatically create a valid Grid corridor from the live market price when
  // the user has not supplied explicit bounds or when existing bounds are out of scale.
  useEffect(() => {
    if (!isOpen || marketPrice <= 0) return;
    if (botMode !== 'Grid Only' && botMode !== 'Avarage+Grid') return;
    
    const isScaleCompatible = minPriceNum > 0 && maxPriceNum > minPriceNum
      && minPriceNum <= marketPrice * 1.5
      && minPriceNum >= marketPrice * 0.001;

    if (isScaleCompatible) return;

    const gridCount = Math.max(1, Number(gridLayers) || 1);
    const downsidePct = Math.min(50, Math.max(5, gridCount * 1.5));
    const upsidePct = Math.max(3, Number(gridProfitPct) || 1.2);
    const derivedMin = Number((marketPrice * (1 - downsidePct / 100)).toFixed(8));
    const derivedMax = Number((marketPrice * (1 + upsidePct / 100)).toFixed(8));

    if (derivedMin > 0 && derivedMax > derivedMin) {
      setMinPrice(derivedMin.toFixed(8));
      setMaxPrice(derivedMax.toFixed(8));
    }
  }, [isOpen, botMode, marketPrice, gridLayers, gridProfitPct, minPriceNum, maxPriceNum, previewPair]);`;

const newEffect = `  // Automatically create a valid Grid corridor from the live market price when
  // the user has not supplied explicit bounds or when existing bounds are out of scale.
  useEffect(() => {
    if (!isOpen || marketPrice <= 0) return;
    if (botMode !== 'Grid Only' && botMode !== 'Avarage+Grid') return;
    if (hasAutoGeneratedGridRef.current) return;
    
    const isScaleCompatible = minPriceNum > 0 && maxPriceNum > minPriceNum
      && minPriceNum <= marketPrice * 1.5
      && minPriceNum >= marketPrice * 0.001;

    if (isScaleCompatible) {
      hasAutoGeneratedGridRef.current = true;
      return;
    }

    const gridCount = Math.max(1, Number(gridLayers) || 1);
    const downsidePct = Math.min(50, Math.max(5, gridCount * 1.5));
    const upsidePct = Math.max(3, Number(gridProfitPct) || 1.2);
    const derivedMin = Number((marketPrice * (1 - downsidePct / 100)).toFixed(8));
    const derivedMax = Number((marketPrice * (1 + upsidePct / 100)).toFixed(8));

    if (derivedMin > 0 && derivedMax > derivedMin) {
      setMinPrice(derivedMin.toFixed(8));
      setMaxPrice(derivedMax.toFixed(8));
      hasAutoGeneratedGridRef.current = true;
    }
  }, [isOpen, botMode, marketPrice, gridLayers, gridProfitPct, previewPair]);`;

code = code.replace(oldEffect, newEffect);

// 4. Fix handleSave error message
const oldSaveValidation = `    if ((botMode === 'Grid Only' || botMode === 'Avarage+Grid') && !(marketPrice > 0 && minPriceNum > 0 && maxPriceNum > minPriceNum)) {
      alert('Harga market belum tersedia untuk membentuk range Grid. Tunggu sinkronisasi harga exchange lalu coba lagi.');
      return;
    }`;

const newSaveValidation = `    if ((botMode === 'Grid Only' || botMode === 'Avarage+Grid')) {
      if (marketPrice <= 0) {
        alert('Harga market belum tersedia untuk membentuk range Grid. Tunggu sinkronisasi harga exchange lalu coba lagi.');
        return;
      }
      if (!(minPriceNum > 0 && maxPriceNum > minPriceNum)) {
        alert('Mode Grid membutuhkan rentang harga (Min Price dan Max Price) yang valid. Silakan isi Batas Bawah dan Batas Atas.');
        return;
      }
    }`;

code = code.replace(oldSaveValidation, newSaveValidation);

fs.writeFileSync(file, code);
